package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class ImputationChecks {
    static int checks;
    static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid imputation input accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);Random rng=new Random(227711);double[][] raw=new double[180][2];for(int i=0;i<raw.length;i++){double x=rng.nextGaussian();raw[i][0]=2+x;raw[i][1]=-1+.6*x+.8*rng.nextGaussian();if(i%5==0)raw[i][0]=Double.NaN;if(i%7==0)raw[i][1]=Double.NaN;}double[][] original=Matrices.copy(raw);var options=new GaussianImputation.Options(8,100,99223);var imputed=GaussianImputation.impute(raw,options,null);var again=GaussianImputation.impute(raw,options,null);var completed=imputed.completed();require(completed.size()==8&&imputed.sourceRows().size()==174,"Excluded wholly unobserved rows and retained all informative source rows");require(imputed.missingCells()>0,"Missing-cell count");for(int m=0;m<8;m++){require(Arrays.deepEquals(completed.get(m),again.completed().get(m)),"Seeded independent-chain reproducibility");for(int i=0;i<completed.get(m).length;i++)for(int j=0;j<2;j++){double observed=raw[imputed.sourceRows().get(i)-1][j];require(Double.isFinite(completed.get(m)[i][j]),"Completed finite cells");if(Double.isFinite(observed))require(Double.doubleToLongBits(observed)==Double.doubleToLongBits(completed.get(m)[i][j]),"Observed cells preserved bit for bit");}}require(Arrays.deepEquals(original,raw),"Original missing data unchanged");require(!Arrays.deepEquals(completed.get(0),completed.get(1)),"Imputations include stochastic parameter/residual uncertainty");require(Double.isFinite(imputed.maximumSplitRhat()),"Trace convergence screen available");
        var fit=ImputedSem.fit(raw,FimlChecks.saturated(),new ImputedSem.Options(options,FimlSem.Options.defaults(),null,false),null);require(fit.analyses().size()==8&&fit.pooled().terms().size()==5,"Every imputation analyzed and pooled");require(fit.pooled().terms().get(0).pValue()!=fit.pooled().terms().get(0).pValue(),"Generic variance ratio tests suppressed");
        List<RubinPooling.Estimate> estimates=List.of(new RubinPooling.Estimate(List.of("b1","b2"),new double[]{1,2},new double[][]{{.2,.03},{.03,.3}}),new RubinPooling.Estimate(List.of("b1","b2"),new double[]{1.2,1.7},new double[][]{{.22,.02},{.02,.28}}),new RubinPooling.Estimate(List.of("b1","b2"),new double[]{.9,2.3},new double[][]{{.18,.01},{.01,.32}}));var pool=RubinPooling.pool(estimates,.95,null,new boolean[]{true,true});var finite=RubinPooling.pool(estimates,.95,50.0,new boolean[]{true,true});require(finite.terms().get(0).degreesOfFreedom()<50,"Finite-complete-df pooling correction");reject(()->RubinPooling.pool(List.of(estimates.getFirst()),.95,null,new boolean[]{true,true}));reject(()->new GaussianImputation.Options(1,100,1));double[][] absent=Matrices.copy(raw);for(var row:absent)row[1]=Double.NaN;reject(()->GaussianImputation.impute(absent,options,null));Thread.currentThread().interrupt();try{GaussianImputation.impute(raw,options,null);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        // Independently checked inverse-Wishart moments, separate from data augmentation.
        double[][] scatter={{3,.4},{.4,2}},average=new double[2][2];Random draws=new Random(44229);int samples=20000;for(int k=0;k<samples;k++){var covariance=GaussianImputation.inverseWishart(scatter,20,draws);for(int i=0;i<2;i++)for(int j=0;j<2;j++)average[i][j]+=covariance.getEntry(i,j)/samples;}for(int i=0;i<2;i++)for(int j=0;j<2;j++)require(Math.abs(average[i][j]-scatter[i][j]/17)<.003,"Inverse-Wishart posterior covariance expectation");
        Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject record=new JsonObject();record.add("observations",gson.toJsonTree(raw));record.add("imputation",gson.toJsonTree(imputed));record.add("fit",gson.toJsonTree(fit));record.add("poolInputs",gson.toJsonTree(estimates));record.add("pool",gson.toJsonTree(pool));record.add("finitePool",gson.toJsonTree(finite));record.add("inverseWishartMean",gson.toJsonTree(average));record.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(record));System.out.println("Imputation checks: "+checks);
    }
}
